D = {"R": "G", "G": "B", "B": "R"}          # a cup of colour t is closed by D[t]


def okw(s):
    t = []
    n = len(s)
    if not s:
        return False
    for i in range(n):
        h = s[i]
        if t and h == D[t[-1]]:
            t.pop()
        else:
            t.append(h)
        if not t and i < n - 1:
            return False
    return not t


def build(r, t, m):
    """A single nested tower of m cup-pairs whose outermost pair is (t, D[t])."""
    inner = m - 1
    parts = []
    while inner > 0:
        k = r.randint(1, inner)
        ch = r.choice([x for x in "RGB" if x != D[t]])
        parts.append(build(r, ch, k))
        inner -= k
    return t + "".join(parts) + D[t]


def generate(seed):
    r = random.Random(seed)
    for _ in range(400):
        w = build(r, r.choice("RGB"), r.randint(6, 9))
        if min(w.count(x) for x in "RGB") < 2:
            continue
        cs = list(w)
        for _ in range(80):
            r.shuffle(cs)
            s = "".join(cs)
            if not okw(s):
                return s
    return "RBGRBGRGBGBG"

